              "\"mail\"",
              "\"iphone\"",
              "\"ipad\"",
              "\"android\"",
              "\"android_hd\"",
              "\"winphone\"",
              "\"win8\"",
              "\"wap\"",
              "\"weixin\"",
              "\"api\"",
              "\"hook\"",
              "\"fetch\"",
              "\"windows\"",
              "\"mac\"",
              "\"h5\"",
              "\"flow\""
