    "version": "2.0.0",
    "type": "POST",
    "url": "/v2/testhub/testcase_properties",
    "title": "",
    "permission": [
      {
        "name": "企业令牌/用户令牌"
      }
    ],
    "scopes": [
      {
        "name": "pcp:write:testhub:configuration"
      }
    ],
    "group": "用例配置",
    "name": "创建一个用例属性",
    "description": "<p>用于创建一个用例属性。</p>",
    "parameter": {
      "fields": {
        "Parameter": [
          {
            "group": "Parameter",
            "type": "String",
            "optional": false,
            "field": "name",
            "description": "<p>用例属性的名称。在一个企业中这个名称是唯一的。</p>"
          },
          {
            "group": "Parameter",
            "type": "String",
            "allowedValues": [
              "text",
              "textarea",
              "select",
              "multi_select",
              "cascade_select",
              "cascade_multi_select",
              "member",
              "members",
              "date",
              "number",
              "progress",
              "rate",
              "link",
              "referred_select",
              "referred_multi_select"
            ],
            "optional": false,
            "field": "type",
            "description": "<p>用例属性的类型。</p>"
          },
          {
            "group": "Parameter",
            "type": "String",
            "allowedValues": [
              "product",
              "project",
              "library",
              "space"
            ],
            "optional": true,
            "field": "referred_object_type",
            "description": "<p>引用对象类型。创建 <code>referred_select,referred_multi_select</code> 属性时必填，更新已有引用选择属性时可用于调整引用对象类型。</p>"
          },
          {
            "group": "Parameter",
            "type": "Object[]",
            "optional": true,
            "field": "options",
            "description": "<p>选择项列表。当用例属性类型为 <code>select,multi_select,cascade_select,cascade_multi_select</code> 时可选填此项。</p>"
          },
          {
            "group": "Parameter",
            "type": "String",
            "optional": true,
            "field": "options.id",
            "description": "<p>选择项 id。该值在选择项中是唯一的。</p>"
          },
          {
            "group": "Parameter",
            "type": "String",
            "optional": false,
            "field": "options.text",
            "description": "<p>选择项内容。该值在选择项中是唯一的。</p>"
          },
          {
            "group": "Parameter",
            "type": "String",
            "optional": true,
            "field": "options.parent_id",
            "description": "<p>选择项父级 id。当属性类型为 <code>cascade_select,cascade_multi_select</code> 时，<code>parent_id</code> 参数有效，用于构建级联类型选择项之间的父子关系，最多存在 4 级。</p>"
          }
        ]
      },
      "examples": [
        {
          "title": "请求示例：",
          "content": "{\n    \"name\": \"严重程度\",\n    \"type\": \"select\",\n    \"options\": [\n        {\n            \"text\": \"严重\"\n        },\n        {\n            \"text\": \"一般\"\n        }\n    ]\n}",
          "type": "json"
        }
      ]
    },
    "success": {
      "fields": {
        "资源属性": [
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "id",
            "description": "<p>用例属性的 id。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "url",
            "description": "<p>用例属性的资源地址。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "name",
            "description": "<p>用例属性的名称。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "type",
            "description": "<p>用例属性的类型。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "referred_object_type",
            "description": "<p>引用对象类型。</p>"
          },
          {
            "group": "资源属性",
            "type": "Object[]",
            "optional": false,
            "field": "options",
            "description": "<p>下拉选项值。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "options.id",
            "description": "<p>选择项 id。该值在选择项中是唯一的。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "options.text",
            "description": "<p>选择项内容。该值在选择项中是唯一的。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "options.color",
            "description": "<p>选择项颜色。</p>"
          },
          {
            "group": "资源属性",
            "type": "String",
            "optional": false,
            "field": "options.parent_id",
            "description": "<p>选择项父级 id。当属性类型为 <code>cascade_select</code> 或 <code>cascade_multi_select</code> 时返回，用于表示级联选择项的父子关系。</p>"
          },
          {
            "group": "资源属性",
            "type": "Number",
            "optional": false,
            "field": "is_removable",
            "description": "<p>是否允许删除。</p>"
          },
          {
            "group": "资源属性",
            "type": "Number",
            "optional": false,
            "field": "is_name_editable",
            "description": "<p>是否允许修改名称。</p>"
          },
          {
            "group": "资源属性",
            "type": "Number",
            "optional": false,
            "field": "is_options_editable",
            "description": "<p>是否允许修改下拉选项值。</p>"
          }
        ]
      },
      "examples": [
        {
          "title": "响应示例：",
          "content": "{\n    \"id\": \"severity\",\n    \"url\": \"https://{rest_api_root}/v2/testhub/testcase_properties/severity\",\n    \"name\": \"严重程度\",\n    \"type\": \"select\",\n    \"options\": [\n        {\n            \"id\": \"5efb1859110533727a82c603\",\n            \"text\": \"严重\",\n            \"color\": \"#FF7575\"\n        },\n        {\n            \"id\": \"5efb1859110533727a82c604\",\n            \"text\": \"一般\",\n            \"color\": \"#FF7575\"\n        }\n    ],\n    \"is_removable\": 1,\n    \"is_name_editable\": 1,\n    \"is_options_editable\": 1\n}",
          "type": "json"
        }
      ]
    },
